  region = c("Norte", "Nordeste", "Norte", "Nordeste", "Centro-Oeste", "Sudeste", "Centro-Oeste", "Nordeste", "Centro-Oeste", "Centro-Oeste", "Sudeste", "Norte", "Nordeste", "Sul", "Nordeste", "Nordeste", "Nordeste", "Nordeste", "Sudeste", "Sul", "Sul", "Norte", "Norte", "Sudeste", "Norte", "Norte", "Nordeste"),
  population_2022 = c(906876, 3365351, 877613, 14985284, 3094325, 4108508, 7206589, 7153262, 3567234, 2839188, 21411923, 8690745, 4059905, 11597484, 9674793, 3289290, 3560903, 2338474, 17463349, 11466630, 7338473, 1815278, 652713, 46649132, 1607363, 4269995, 9240580),
