#' Get Complete Brazilian Administrative Hierarchy
#' 
#' Returns the complete Brazilian administrative hierarchy with regions,
#' states, and basic demographic information.
#' 
#' @param include_demographics Logical whether to include population and area data
#' @return data.frame with complete administrative hierarchy
#' @export
get_brazilian_hierarchy <- function(include_demographics = TRUE) {
  cat("🏛️ Building Brazilian administrative hierarchy...\n")
  
  tryCatch({
    # Add region information to states
    hierarchy <- BRAZILIAN_STATES %>%
      mutate(
        region_code = case_when(
          region == "Norte" ~ 1,
          region == "Nordeste" ~ 2,
          region == "Sudeste" ~ 3,
          region == "Sul" ~ 4,
          region == "Centro-Oeste" ~ 5,
          TRUE ~ NA_real_
        ),
        region_color = case_when(
          region == "Norte" ~ "#27AE60",
          region == "Nordeste" ~ "#E74C3C",
          region == "Sudeste" ~ "#3498DB",
          region == "Sul" ~ "#9B59B6",
          region == "Centro-Oeste" ~ "#F39C12",
          TRUE ~ "#95A5A6"
        )\n      )\n    \n    if (!include_demographics) {\n      hierarchy <- hierarchy %>%\n        select(-population_2022, -area_km2)\n    }\n    \n    cat(\"✅ Brazilian hierarchy created with\", nrow(hierarchy), \"states and\", \n        length(unique(hierarchy$region)), \"regions\\n\")\n    \n    return(hierarchy)\n    \n  }, error = function(e) {\n    warning(\"Error building Brazilian hierarchy: \", e$message)\n    return(data.frame())\n  })\n}\n\n#' Map Document Locations to Administrative Divisions\n#' \n#' Maps legislative documents to Brazilian administrative divisions based on\n#' location information in the documents.\n#' \n#' @param documents_data data.frame with legislative documents\n#' @param location_column Character name of location column\n#' @param hierarchy_data data.frame with Brazilian hierarchy (optional)\n#' @return data.frame with enhanced geographic information\n#' @export\nmap_to_administrative_divisions <- function(documents_data, location_column = \"localidade\", \n                                           hierarchy_data = NULL) {\n  \n  cat(\"🗺️ Mapping documents to Brazilian administrative divisions...\\n\")\n  \n  tryCatch({\n    if (is.null(hierarchy_data)) {\n      hierarchy_data <- get_brazilian_hierarchy()\n    }\n    \n    if (nrow(documents_data) == 0) {\n      warning(\"No documents data provided\")\n      return(documents_data)\n    }\n    \n    # Enhanced state detection patterns\n    enhanced_docs <- documents_data %>%\n      mutate(\n        # Extract state information using multiple methods\n        estado_detected = case_when(\n          # Direct state abbreviations\n          grepl(\"\\\\bAC\\\\b\", get(location_column), ignore.case = TRUE) ~ \"AC\",\n          grepl(\"\\\\bAL\\\\b\", get(location_column), ignore.case = TRUE) ~ \"AL\",\n          grepl(\"\\\\bAP\\\\b\", get(location_column), ignore.case = TRUE) ~ \"AP\",\n          grepl(\"\\\\bAM\\\\b\", get(location_column), ignore.case = TRUE) ~ \"AM\",\n          grepl(\"\\\\bBA\\\\b\", get(location_column), ignore.case = TRUE) ~ \"BA\",\n          grepl(\"\\\\bCE\\\\b\", get(location_column), ignore.case = TRUE) ~ \"CE\",\n          grepl(\"\\\\bDF\\\\b|Brasília|BRASILIA|Distrito Federal\", get(location_column), ignore.case = TRUE) ~ \"DF\",\n          grepl(\"\\\\bES\\\\b\", get(location_column), ignore.case = TRUE) ~ \"ES\",\n          grepl(\"\\\\bGO\\\\b\", get(location_column), ignore.case = TRUE) ~ \"GO\",\n          grepl(\"\\\\bMA\\\\b\", get(location_column), ignore.case = TRUE) ~ \"MA\",\n          grepl(\"\\\\bMT\\\\b\", get(location_column), ignore.case = TRUE) ~ \"MT\",\n          grepl(\"\\\\bMS\\\\b\", get(location_column), ignore.case = TRUE) ~ \"MS\",\n          grepl(\"\\\\bMG\\\\b\", get(location_column), ignore.case = TRUE) ~ \"MG\",\n          grepl(\"\\\\bPA\\\\b\", get(location_column), ignore.case = TRUE) ~ \"PA\",\n          grepl(\"\\\\bPB\\\\b\", get(location_column), ignore.case = TRUE) ~ \"PB\",\n          grepl(\"\\\\bPR\\\\b\", get(location_column), ignore.case = TRUE) ~ \"PR\",\n          grepl(\"\\\\bPE\\\\b\", get(location_column), ignore.case = TRUE) ~ \"PE\",\n          grepl(\"\\\\bPI\\\\b\", get(location_column), ignore.case = TRUE) ~ \"PI\",\n          grepl(\"\\\\bRJ\\\\b\", get(location_column), ignore.case = TRUE) ~ \"RJ\",\n          grepl(\"\\\\bRN\\\\b\", get(location_column), ignore.case = TRUE) ~ \"RN\",\n          grepl(\"\\\\bRS\\\\b\", get(location_column), ignore.case = TRUE) ~ \"RS\",\n          grepl(\"\\\\bRO\\\\b\", get(location_column), ignore.case = TRUE) ~ \"RO\",\n          grepl(\"\\\\bRR\\\\b\", get(location_column), ignore.case = TRUE) ~ \"RR\",\n          grepl(\"\\\\bSC\\\\b\", get(location_column), ignore.case = TRUE) ~ \"SC\",\n          grepl(\"\\\\bSP\\\\b\", get(location_column), ignore.case = TRUE) ~ \"SP\",\n          grepl(\"\\\\bSE\\\\b\", get(location_column), ignore.case = TRUE) ~ \"SE\",\n          grepl(\"\\\\bTO\\\\b\", get(location_column), ignore.case = TRUE) ~ \"TO\",\n          \n          # Full state names\n          grepl(\"Acre\", get(location_column), ignore.case = TRUE) ~ \"AC\",\n          grepl(\"Alagoas\", get(location_column), ignore.case = TRUE) ~ \"AL\",\n          grepl(\"Amapá|Amapa\", get(location_column), ignore.case = TRUE) ~ \"AP\",\n          grepl(\"Amazonas\", get(location_column), ignore.case = TRUE) ~ \"AM\",\n          grepl(\"Bahia\", get(location_column), ignore.case = TRUE) ~ \"BA\",\n          grepl(\"Ceará|Ceara\", get(location_column), ignore.case = TRUE) ~ \"CE\",\n          grepl(\"Espírito Santo|Espirito Santo\", get(location_column), ignore.case = TRUE) ~ \"ES\",\n          grepl(\"Goiás|Goias\", get(location_column), ignore.case = TRUE) ~ \"GO\",\n          grepl(\"Maranhão|Maranhao\", get(location_column), ignore.case = TRUE) ~ \"MA\",\n          grepl(\"Mato Grosso do Sul\", get(location_column), ignore.case = TRUE) ~ \"MS\",\n          grepl(\"Mato Grosso\", get(location_column), ignore.case = TRUE) ~ \"MT\",\n          grepl(\"Minas Gerais\", get(location_column), ignore.case = TRUE) ~ \"MG\",\n          grepl(\"Pará|Para\", get(location_column), ignore.case = TRUE) ~ \"PA\",\n          grepl(\"Paraíba|Paraiba\", get(location_column), ignore.case = TRUE) ~ \"PB\",\n          grepl(\"Paraná|Parana\", get(location_column), ignore.case = TRUE) ~ \"PR\",\n          grepl(\"Pernambuco\", get(location_column), ignore.case = TRUE) ~ \"PE\",\n          grepl(\"Piauí|Piaui\", get(location_column), ignore.case = TRUE) ~ \"PI\",\n          grepl(\"Rio de Janeiro\", get(location_column), ignore.case = TRUE) ~ \"RJ\",\n          grepl(\"Rio Grande do Norte\", get(location_column), ignore.case = TRUE) ~ \"RN\",\n          grepl(\"Rio Grande do Sul\", get(location_column), ignore.case = TRUE) ~ \"RS\",\n          grepl(\"Rondônia|Rondonia\", get(location_column), ignore.case = TRUE) ~ \"RO\",\n          grepl(\"Roraima\", get(location_column), ignore.case = TRUE) ~ \"RR\",\n          grepl(\"Santa Catarina\", get(location_column), ignore.case = TRUE) ~ \"SC\",\n          grepl(\"São Paulo|Sao Paulo|SAO PAULO\", get(location_column), ignore.case = TRUE) ~ \"SP\",\n          grepl(\"Sergipe\", get(location_column), ignore.case = TRUE) ~ \"SE\",\n          grepl(\"Tocantins\", get(location_column), ignore.case = TRUE) ~ \"TO\",\n          \n          # Capital cities and major cities\n          grepl(\"Rio Branco\", get(location_column), ignore.case = TRUE) ~ \"AC\",\n          grepl(\"Maceió|Maceio\", get(location_column), ignore.case = TRUE) ~ \"AL\",\n          grepl(\"Macapá|Macapa\", get(location_column), ignore.case = TRUE) ~ \"AP\",\n          grepl(\"Manaus\", get(location_column), ignore.case = TRUE) ~ \"AM\",\n          grepl(\"Salvador\", get(location_column), ignore.case = TRUE) ~ \"BA\",\n          grepl(\"Fortaleza\", get(location_column), ignore.case = TRUE) ~ \"CE\",\n          grepl(\"Vitória|Vitoria\", get(location_column), ignore.case = TRUE) ~ \"ES\",\n          grepl(\"Goiânia|Goiania\", get(location_column), ignore.case = TRUE) ~ \"GO\",\n          grepl(\"São Luís|Sao Luis|SAO LUIS\", get(location_column), ignore.case = TRUE) ~ \"MA\",\n          grepl(\"Cuiabá|Cuiaba\", get(location_column), ignore.case = TRUE) ~ \"MT\",\n          grepl(\"Campo Grande\", get(location_column), ignore.case = TRUE) ~ \"MS\",\n          grepl(\"Belo Horizonte\", get(location_column), ignore.case = TRUE) ~ \"MG\",\n          grepl(\"Belém|Belem\", get(location_column), ignore.case = TRUE) ~ \"PA\",\n          grepl(\"João Pessoa|Joao Pessoa|JOAO PESSOA\", get(location_column), ignore.case = TRUE) ~ \"PB\",\n          grepl(\"Curitiba\", get(location_column), ignore.case = TRUE) ~ \"PR\",\n          grepl(\"Recife\", get(location_column), ignore.case = TRUE) ~ \"PE\",\n          grepl(\"Teresina\", get(location_column), ignore.case = TRUE) ~ \"PI\",\n          grepl(\"Natal\", get(location_column), ignore.case = TRUE) ~ \"RN\",\n          grepl(\"Porto Alegre\", get(location_column), ignore.case = TRUE) ~ \"RS\",\n          grepl(\"Porto Velho\", get(location_column), ignore.case = TRUE) ~ \"RO\",\n          grepl(\"Boa Vista\", get(location_column), ignore.case = TRUE) ~ \"RR\",\n          grepl(\"Florianópolis|Florianopolis\", get(location_column), ignore.case = TRUE) ~ \"SC\",\n          grepl(\"Aracaju\", get(location_column), ignore.case = TRUE) ~ \"SE\",\n          grepl(\"Palmas\", get(location_column), ignore.case = TRUE) ~ \"TO\",\n          \n          # Federal level indicators\n          grepl(\"Brasil|Brazil|Federal|União|Uniao|Nacional\", get(location_column), ignore.case = TRUE) ~ \"BR\",\n          \n          TRUE ~ NA_character_\n        )\n      )\n    \n    # Join with hierarchy data\n    result <- enhanced_docs %>%\n      left_join(\n        hierarchy_data,\n        by = c(\"estado_detected\" = \"state_abbr\")\n      ) %>%\n      mutate(\n        # Administrative level classification\n        administrative_level = case_when(\n          estado_detected == \"BR\" ~ \"federal\",\n          !is.na(estado_detected) ~ \"state\",\n          grepl(\"município|municipal|prefeitura|câmara\", get(location_column), ignore.case = TRUE) ~ \"municipal\",\n          TRUE ~ \"unknown\"\n        ),\n        \n        # Geographic scope\n        geographic_scope = case_when(\n          administrative_level == \"federal\" ~ \"Nacional\",\n          administrative_level == \"state\" ~ paste(\"Estadual -\", region),\n          administrative_level == \"municipal\" ~ \"Municipal\",\n          TRUE ~ \"Não Identificado\"\n        )\n      )\n    \n    # Calculate mapping statistics\n    mapped_count <- sum(!is.na(result$estado_detected) & result$estado_detected != \"BR\")\n    federal_count <- sum(result$estado_detected == \"BR\", na.rm = TRUE)\n    unmapped_count <- sum(is.na(result$estado_detected))\n    \n    cat(\"✅ Administrative division mapping complete:\\n\")\n    cat(\"   - Mapped to states:\", mapped_count, \"documents\\n\")\n    cat(\"   - Federal level:\", federal_count, \"documents\\n\")\n    cat(\"   - Unmapped:\", unmapped_count, \"documents\\n\")\n    cat(\"   - Success rate:\", round((mapped_count + federal_count) / nrow(result) * 100, 1), \"%\\n\")\n    \n    return(result)\n    \n  }, error = function(e) {\n    warning(\"Error mapping to administrative divisions: \", e$message)\n    return(documents_data)\n  })\n}\n\n#' Analyze Regional Distribution of Legislative Documents\n#' \n#' Provides comprehensive analysis of document distribution across Brazilian regions.\n#' \n#' @param mapped_documents data.frame with documents mapped to administrative divisions\n#' @param analysis_type Character type of analysis (\"summary\", \"detailed\", \"temporal\")\n#' @return list with analysis results\n#' @export\nanalyze_regional_distribution <- function(mapped_documents, analysis_type = \"summary\") {\n  cat(\"📊 Analyzing regional distribution of legislative documents...\\n\")\n  \n  tryCatch({\n    if (nrow(mapped_documents) == 0) {\n      return(list(error = \"No mapped documents available\"))\n    }\n    \n    analysis_result <- switch(analysis_type,\n      \"summary\" = {\n        # Basic regional summary\n        regional_summary <- mapped_documents %>%\n          filter(!is.na(region)) %>%\n          group_by(region, region_color) %>%\n          summarise(\n            total_documents = n(),\n            states_count = n_distinct(state_abbr, na.rm = TRUE),\n            categories_count = n_distinct(categoria, na.rm = TRUE),\n            date_range_start = min(data, na.rm = TRUE),\n            date_range_end = max(data, na.rm = TRUE),\n            .groups = \"drop\"\n          ) %>%\n          arrange(desc(total_documents))\n        \n        # Overall statistics\n        overall_stats <- list(\n          total_documents = nrow(mapped_documents),\n          documents_with_region = sum(!is.na(mapped_documents$region)),\n          coverage_percentage = round((sum(!is.na(mapped_documents$region)) / nrow(mapped_documents)) * 100, 1),\n          regions_covered = n_distinct(mapped_documents$region, na.rm = TRUE),\n          states_covered = n_distinct(mapped_documents$state_abbr, na.rm = TRUE)\n        )\n        \n        list(\n          regional_summary = regional_summary,\n          overall_stats = overall_stats\n        )\n      },\n      \n      \"detailed\" = {\n        # Detailed state-by-state analysis\n        state_analysis <- mapped_documents %>%\n          filter(!is.na(state_abbr)) %>%\n          group_by(region, state_abbr, state_name, capital) %>%\n          summarise(\n            total_documents = n(),\n            documents_per_capita = ifelse(!is.na(population_2022), \n                                        round((n() / population_2022) * 100000, 2), NA),\n            documents_per_km2 = ifelse(!is.na(area_km2), \n                                     round(n() / area_km2, 4), NA),\n            categories = paste(unique(categoria)[!is.na(unique(categoria))], collapse = \", \"),\n            dominant_category = names(sort(table(categoria), decreasing = TRUE))[1],\n            .groups = \"drop\"\n          ) %>%\n          arrange(region, desc(total_documents))\n        \n        # Regional comparisons\n        regional_comparison <- mapped_documents %>%\n          filter(!is.na(region)) %>%\n          group_by(region) %>%\n          summarise(\n            total_documents = n(),\n            avg_docs_per_state = round(n() / n_distinct(state_abbr), 1),\n            document_density_score = round(n() / sum(area_km2, na.rm = TRUE) * 1000, 2),\n            .groups = \"drop\"\n          )\n        \n        list(\n          state_analysis = state_analysis,\n          regional_comparison = regional_comparison\n        )\n      },\n      \n      \"temporal\" = {\n        # Temporal analysis by region\n        if (!\"data\" %in% names(mapped_documents)) {\n          return(list(error = \"No date information available for temporal analysis\"))\n        }\n        \n        temporal_analysis <- mapped_documents %>%\n          filter(!is.na(region) & !is.na(data)) %>%\n          mutate(\n            year = as.numeric(format(as.Date(data), \"%Y\")),\n            month = as.numeric(format(as.Date(data), \"%m\"))\n          ) %>%\n          filter(year >= 2000 & year <= 2025) %>%\n          group_by(region, year) %>%\n          summarise(\n            documents_count = n(),\n            .groups = \"drop\"\n          ) %>%\n          arrange(region, year)\n        \n        # Trend analysis\n        trend_analysis <- temporal_analysis %>%\n          group_by(region) %>%\n          summarise(\n            total_years = n_distinct(year),\n            avg_docs_per_year = round(mean(documents_count), 1),\n            peak_year = year[which.max(documents_count)],\n            peak_documents = max(documents_count),\n            .groups = \"drop\"\n          )\n        \n        list(\n          temporal_data = temporal_analysis,\n          trend_analysis = trend_analysis\n        )\n      },\n      \n      # Default summary\n      {\n        mapped_documents %>%\n          filter(!is.na(region)) %>%\n          group_by(region) %>%\n          summarise(total_documents = n(), .groups = \"drop\")\n      }\n    )\n    \n    cat(\"✅ Regional distribution analysis complete\\n\")\n    return(analysis_result)\n    \n  }, error = function(e) {\n    warning(\"Error analyzing regional distribution: \", e$message)\n    return(list(error = e$message))\n  })\n}\n\n#' Create Administrative Division Hierarchy Visualization\n#' \n#' Creates data structure for visualizing Brazilian administrative hierarchy.\n#' \n#' @param document_counts data.frame with document counts by administrative division\n#' @return list with hierarchy visualization data\n#' @export\ncreate_hierarchy_visualization <- function(document_counts) {\n  cat(\"🌳 Creating administrative hierarchy visualization...\\n\")\n  \n  tryCatch({\n    hierarchy_data <- get_brazilian_hierarchy()\n    \n    # Build hierarchy tree structure\n    hierarchy_tree <- list(\n      name = \"Brasil\",\n      level = \"country\",\n      children = list()\n    )\n    \n    # Add regions\n    for (region_name in unique(hierarchy_data$region)) {\n      region_states <- hierarchy_data %>% filter(region == region_name)\n      region_docs <- sum(document_counts$total_documents[document_counts$region == region_name], na.rm = TRUE)\n      \n      region_node <- list(\n        name = region_name,\n        level = \"region\",\n        document_count = region_docs,\n        color = region_states$region_color[1],\n        children = list()\n      )\n      \n      # Add states within region\n      for (i in 1:nrow(region_states)) {\n        state <- region_states[i, ]\n        state_docs <- document_counts$total_documents[document_counts$state_abbr == state$state_abbr]\n        if (length(state_docs) == 0) state_docs <- 0\n        \n        state_node <- list(\n          name = state$state_name,\n          abbr = state$state_abbr,\n          level = \"state\",\n          capital = state$capital,\n          document_count = state_docs,\n          population = state$population_2022,\n          area = state$area_km2\n        )\n        \n        region_node$children <- append(region_node$children, list(state_node))\n      }\n      \n      hierarchy_tree$children <- append(hierarchy_tree$children, list(region_node))\n    }\n    \n    cat(\"✅ Hierarchy visualization created with\", length(hierarchy_tree$children), \"regions\\n\")\n    return(hierarchy_tree)\n    \n  }, error = function(e) {\n    warning(\"Error creating hierarchy visualization: \", e$message)\n    return(list())\n  })\n}\n\n#' Get Transport Corridor Information\n#' \n#' Returns information about major Brazilian transport corridors for legislative analysis.\n#' \n#' @return list with transport corridor data\n#' @export\nget_transport_corridors <- function() {\n  transport_corridors <- list(\n    \"sp_rj\" = list(\n      name = \"São Paulo - Rio de Janeiro\",\n      description = \"Principal corredor econômico do Brasil\",\n      states = c(\"SP\", \"RJ\"),\n      modal_types = c(\"Rodoviário\", \"Ferroviário\", \"Aéreo\"),\n      major_highways = c(\"BR-116\", \"Via Dutra\"),\n      economic_importance = \"Alto\"\n    ),\n    \n    \"bh_vit\" = list(\n      name = \"Belo Horizonte - Vitória\",\n      description = \"Corredor de exportação de minério\",\n      states = c(\"MG\", \"ES\"),\n      modal_types = c(\"Ferroviário\", \"Rodoviário\"),\n      major_highways = c(\"BR-381\"),\n      economic_importance = \"Alto\"\n    ),\n    \n    \"sp_santos\" = list(\n      name = \"São Paulo - Santos\",\n      description = \"Principal corredor portuário do Brasil\",\n      states = c(\"SP\"),\n      modal_types = c(\"Rodoviário\", \"Ferroviário\"),\n      major_highways = c(\"Rodovia Anchieta\", \"Rodovia Imigrantes\"),\n      economic_importance = \"Crítico\"\n    ),\n    \n    \"bsb_go\" = list(\n      name = \"Brasília - Goiânia\",\n      description = \"Corredor do Centro-Oeste\",\n      states = c(\"DF\", \"GO\"),\n      modal_types = c(\"Rodoviário\"),\n      major_highways = c(\"BR-060\"),\n      economic_importance = \"Médio\"\n    ),\n    \n    \"rmsp\" = list(\n      name = \"Região Metropolitana de São Paulo\",\n      description = \"Maior complexo metropolitano do Brasil\",\n      states = c(\"SP\"),\n      modal_types = c(\"Rodoviário\", \"Ferroviário\", \"Metro\", \"Aéreo\"),\n      major_highways = c(\"Rodoanel\", \"Marginal Tietê\", \"Marginal Pinheiros\"),\n      economic_importance = \"Crítico\"\n    )\n  )\n  \n  return(transport_corridors)\n}\n\ncat(\"✅ Brazilian administrative division mapping system loaded successfully\\n\")